ALTER TABLE t ADD COLUMN a Int64 NOT NULL DEFAULT 1, ADD b Int64 NOT NULL, ADD COLUMN c Int64 DEFAULT 2, ADD COLUMN d Int64;
ALTER TABLE t ADD INDEX t_u GLOBAL UNIQUE ON (a), ADD INDEX t_v GLOBAL ON (b);
ALTER TABLE t ADD INDEX t_w LOCAL UNIQUE SYNC USING secondary ON (c) COVER (d);
ALTER TABLE IF EXISTS `dir/t` ADD INDEX `t-x` GLOBAL UNIQUE ON (`a`, b);
CREATE TABLE n (id Uint64 NOT NULL, v Utf8, PRIMARY KEY (id), INDEX n_v GLOBAL UNIQUE SYNC ON (v));
